{{
  (() => {
    const value =
      CW_Constructor.model.drawerPosts;

    let directRows = -1;
    let decodedRows = -1;

    if (typeof value === "string") {
      try {
        directRows =
          JSON.parse(value).length;
      } catch (e) {}

      try {
        decodedRows =
          JSON.parse(
            decodeURIComponent(value)
          ).length;
      } catch (e) {}
    }

    return JSON.stringify({
      queryRows:
        (Q_DrawerPosts.data || []).length,

      modelType:
        Array.isArray(value)
          ? "array"
          : typeof value,

      modelLength:
        typeof value === "string"
          ? value.length
          : -1,

      directRows,
      decodedRows
    });
  })()
}}
